                                if n:find(jOO0Ill0oI0) or n:find(Rl1I000lI0o) or n:find(y0l1lI10IIl) or n:find(zOO1IoOOlO0) or n:find(yllIOIOl0IO) then
                                    local ok2, data = pcall(require, child)
                                    if ok2 then
